package main

import (
	"crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

type FeatureFlags struct {
	EnableAuditLog    bool `json:"enable_audit_log"`
	UseAtomicWrites   bool `json:"use_atomic_writes"`
	EnableCompression bool `json:"enable_compression"`
	SafeMode          bool `json:"safe_mode"`
}

type Message struct {
	ID        string `json:"id"`
	Topic     string `json:"topic"`
	Payload   string `json:"payload"`
	Timestamp int64  `json:"timestamp"`
	OutputDir string `json:"output_dir"`
}

type QueueConsumer struct {
	mu       sync.Mutex
	flags    FeatureFlags
	baseDir  string
	processed map[string]bool
}

func NewQueueConsumer(baseDir string, flags FeatureFlags) *QueueConsumer {
	return &QueueConsumer{
		flags:    flags,
		baseDir:  baseDir,
		processed: make(map[string]bool),
	}
}

func (qc *QueueConsumer) generateTempName() string {
	b := make([]byte, 16)
	rand.Read(b)
	return hex.EncodeToString(b)
}

func (qc *QueueConsumer) resolveOutputPath(msg Message) (string, error) {
	outputDir := msg.OutputDir
	if outputDir == "" {
		outputDir = "default"
	}

	// Sanitize: reject path traversal in the directory component
	if strings.Contains(outputDir, "..") {
		return "", fmt.Errorf("invalid output directory: path traversal detected")
	}

	targetDir := filepath.Join(qc.baseDir, outputDir)

	// Verify the resolved path is under baseDir
	absTarget, err := filepath.Abs(targetDir)
	if err != nil {
		return "", err
	}
	absBase, err := filepath.Abs(qc.baseDir)
	if err != nil {
		return "", err
	}
	if !strings.HasPrefix(absTarget, absBase+string(os.PathSeparator)) {
		return "", fmt.Errorf("resolved path escapes base directory")
	}

	return targetDir, nil
}

func (qc *QueueConsumer) ensureDirectory(path string) error {
	info, err := os.Lstat(path)
	if err == nil {
		if info.Mode()&os.ModeSymlink != 0 {
			return fmt.Errorf("symlink detected at directory path: %s", path)
		}
		if !info.IsDir() {
			return fmt.Errorf("path exists but is not a directory: %s", path)
		}
		return nil
	}
	return os.MkdirAll(path, 0750)
}

func (qc *QueueConsumer) writePayload(targetDir, filename, payload string) error {
	finalPath := filepath.Join(targetDir, filename)

	if qc.flags.UseAtomicWrites {
		tmpName := qc.generateTempName()
		tmpPath := filepath.Join(targetDir, "."+tmpName+".tmp")

		// Write to temp file first
		if err := os.WriteFile(tmpPath, []byte(payload), 0640); err != nil {
			return err
		}

		// Atomic rename
		if err := os.Rename(tmpPath, finalPath); err != nil {
			os.Remove(tmpPath)
			return err
		}
		return nil
	}

	return os.WriteFile(finalPath, []byte(payload), 0640)
}

func (qc *QueueConsumer) validateFilename(name string) error {
	if strings.Contains(name, "/") || strings.Contains(name, "\\") {
		return fmt.Errorf("invalid filename: contains path separator")
	}
	if strings.HasPrefix(name, ".") {
		return fmt.Errorf("invalid filename: hidden file")
	}
	if name == "" {
		return fmt.Errorf("invalid filename: empty")
	}
	return nil
}

func (qc *QueueConsumer) ProcessMessage(msg Message) error {
	qc.mu.Lock()
	if qc.processed[msg.ID] {
		qc.mu.Unlock()
		return fmt.Errorf("duplicate message: %s", msg.ID)
	}
	qc.processed[msg.ID] = true
	qc.mu.Unlock()

	targetDir, err := qc.resolveOutputPath(msg)
	if err != nil {
		return fmt.Errorf("path resolution failed: %w", err)
	}

	if err := qc.ensureDirectory(targetDir); err != nil {
		return fmt.Errorf("directory validation failed: %w", err)
	}

	filename := fmt.Sprintf("%s_%d.msg", msg.Topic, msg.Timestamp)
	if err := qc.validateFilename(filename); err != nil {
		return fmt.Errorf("filename validation failed: %w", err)
	}

	// When safe_mode is enabled, verify the final path doesn't follow symlinks
	if qc.flags.SafeMode {
		finalPath := filepath.Join(targetDir, filename)
		if info, err := os.Lstat(finalPath); err == nil {
			if info.Mode()&os.ModeSymlink != 0 {
				return fmt.Errorf("symlink detected at output path")
			}
		}
	}

	if err := qc.writePayload(targetDir, filename, msg.Payload); err != nil {
		return fmt.Errorf("write failed: %w", err)
	}

	if qc.flags.EnableAuditLog {
		log.Printf("[AUDIT] Processed message %s to %s/%s", msg.ID, targetDir, filename)
	}

	return nil
}

func main() {
	flagsData, err := os.ReadFile("/etc/mqconsumer/flags.json")
	if err != nil {
		log.Fatalf("Failed to read feature flags: %v", err)
	}

	var flags FeatureFlags
	if err := json.Unmarshal(flagsData, &flags); err != nil {
		log.Fatalf("Failed to parse feature flags: %v", err)
	}

	consumer := NewQueueConsumer("/var/spool/mqconsumer", flags)

	// Simulate consuming from queue
	messages := []Message{
		{ID: "msg-001", Topic: "orders", Payload: "{\"order_id\": 12345}", Timestamp: time.Now().Unix(), OutputDir: "orders"},
		{ID: "msg-002", Topic: "events", Payload: "{\"event\": \"login\"}", Timestamp: time.Now().Unix(), OutputDir: "events"},
	}

	for _, msg := range messages {
		if err := consumer.ProcessMessage(msg); err != nil {
			log.Printf("Error processing message %s: %v", msg.ID, err)
		}
	}
}
